***********************************************************************************************************************************			 ******			 ******	     Tool Locator		 ******	        Patch		 ******                For Version 2.0 ROM only	 ***  ***			 ******			 ******	     May 13, 1989		 ******	   Steven E. Glass		 ******			 ******			 ****************************************************************************************************************************************************************************************************			   **	Copyright (C) 1985-1988	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   ***************************************************************************************************************************************** Change History** 24 Oct 88	Steven Glass** Reorganized the patch code so that the patch could link to parts* of the ROM.  The parts of TS2 that are identical to ROM 3.0 are* made from the same source and object files.  This minimizes* code maintenance.** To make this work, this file now contains a copy of the bootinit* routine, and entries to the equivalent to oEndCall0 and oBusyErr4.*** 13 May 89	Steven Glass** So that the rom and ram patch could agree on certain addresses* I use equates for DummyTable and UserDummyTable.  This way, the * calls that are patched and the calls that are not patched * use the same value.  I wonder what I was thinking before?** This also saves code as the user dummy table does not need to* be changed on boot init to prevent accidental disposal.** 20-Sep-90	Dave Lyons** Added some new call skeletons for 6.0.** 25-Sep-90	Dave Lyons** Added GetIndMessage.** 17-Sep-91	Dave Lyons** Moved some stuff to Tool.Setup.***********************************************************************	include ':::sys.equs.asm';; Use this value in ROM rather than putting it in RAM.;	export DummyTable:equDummyTable	equ $FE01EB	export UserDummyTable:equUserDummyTable	equ $FE01EF****************************************************************** TLTable** This is the Function pointer Table (FPT) for the tool* locator tool set.******************************************************************TLCallTable	proc EXPORT	IMPORT TLBootInit	IMPORT TLStartup	IMPORT TLShutDown	IMPORT TLVersion	IMPORT TLMountVolume	IMPORT TLTextMountVolume	IMPORT SaveTextState	IMPORT RestoreTextState	IMPORT MessageCenter	IMPORT SetDefaultTPT	import MessageByNameTheBeginning	dc.L (TheEnd-TheBeginning)/4 ; call count + 1	dc.L TLBootInit-1		; (01)	dc.L TLStartup-1		; (02)	dc.L TLShutDown-1		; (03)	dc.L TLVersion-1		; (04)	dc.L 0		; TLReset    (05)	 	dc.L 0		; TLStatus   (06)	dc.L 0		; NotImp     (07)	dc.L 0		; NotImp     (08)	dc.L 0		; GetTSPtr   (09)	dc.L 0		; SetTSPtr   (0A)	dc.L 0		; GetFuncPtr (0B)	dc.L 0		; GetWAP     (0C)	dc.L 0		; SetWAP     (0D)	dc.L 0	;[ts] LoadTools-1		; 0E01	dc.L 0	;[ts] LoadOneTool-1		; 0F01	dc.L 0	;[ts] UnloadOneTool-1 	; 1001	dc.L TLMountVolume-1 	; 1101	dc.L TLTextMountVolume-1 	; 1201	dc.L SaveTextState-1 	; 1301	dc.L RestoreTextState-1 	; 1401	dc.L MessageCenter-1 	; 1501	dc.L SetDefaultTPT-1 	; 1601	dc.L MessageByName-1 	; 1701	dc.L 0	;[ts] StartupTools-1 	; 1801	dc.L 0	;[ts] ShutDownTools-1 	; 1901*** New calls for 6.0	dc.l 0	;[ts] GetMsgHandle-1	; 1A01 DAL 20-Sep-90	dc.l 0	;[ts] AcceptRequests-1	; 1C01 DAL 20-Sep-90	dc.l 0	;[ts] SendRequest-1		; 1D01 DAL 20-Sep-90TheEnd	ENDP		*****************************************************************TLBootInit	PROC** This null routine is called when the patch is installed.* it should never be called again.** This routine is also the equivalent to oEndCall0.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:	EXPORT oEndCall0*	longa on	; mode	longi on*** Change History** 13 May 89	Steven Glass** No longer store the address of user dummy table into* U_TPTPtr.*****************************************************************oEndCall0	lda #0	clc	rtl	EndP	END